                forall |k: nat| 0 <= k < HEIGHT ==>
                    lock_stores.dom().contains(lock_for_row(k)) ==>
                    lock_stores[#[trigger] lock_for_row(k)].rows.dom().contains(k)
                    && lock_stores[lock_for_row(k)].rows[k].pt.id() == cell_ids[k as int]
